  LuaManager.env.rawset("print",(JavaFunction)(f,n)->{for(int i=0;i<n;i++)System.out.print((i==0?"":" ")+String.valueOf(f.get(i)));System.out.println();return 0;});LuaManager.env.rawset("body",body);
