  LuaManager.env.rawset("instanceItem",(JavaFunction)(f,n)->{try{String name=(String)f.get(0);var item=module.getItem(name.substring(name.indexOf('.')+1)).InstanceItem(null);item.setID(++nextId);f.push(item);return 1;}catch(Exception e){throw new RuntimeException(e);}});
  LuaManager.env.rawset("wear",(JavaFunction)(f,n)->{body.setWornItem(ItemBodyLocation.SHIRT,(InventoryItem)f.get(0),false);return 0;});
